mapper.select:



        and resident_id = #{residentId}


        and result_id = #{resultId}


        and follow_up_type = #{followUpType}


        and follow_up_status = #{followUpStatus}


        and follow_up_level = #{followUpLevel}


        and assigned_user_id = #{assignedUserId}


        and date_format(assign_date,'%y%m%d') >= date_format(#{params.beginAssignDate},'%y%m%d')


        and date_format(assign_date,'%y%m%d') <= date_format(#{params.endAssignDate},'%y%m%d')


order by follow_up_id desc

select f.follow_up_id, f.resident_id, f.result_id, f.follow_up_type, f.follow_up_status, f.follow_up_level,
       f.assigned_user_id, f.assigned_user_name, f.assign_date, f.complete_date, f.remark,
       f.create_by, f.create_time, f.update_by, f.update_time,
       r.name as resident_name, r.id_card, r.phone, r.gender, r.age, r.district_id, r.district_name,
       sr.blood_result, sr.blood_result_detail, sr.blood_result_date, sr.gastroscopy_result
from gc_follow_up f
         left join gc_resident r on f.resident_id = r.resident_id
         left join gc_screening_result sr on f.result_id = sr.result_id


        and f.resident_id = #{residentId}


        and f.result_id = #{resultId}


        and f.follow_up_type = #{followUpType}


        and f.follow_up_status = #{followUpStatus}


        and f.follow_up_level = #{followUpLevel}


        and f.assigned_user_id = #{assignedUserId}


        and r.name like concat('%', #{params.residentName}, '%')


        and r.id_card like concat('%', #{params.idCard}, '%')


        and r.phone like concat('%', #{params.phone}, '%')


        and date_format(f.assign_date,'%y%m%d') >= date_format(#{params.beginAssignDate},'%y%m%d')


        and date_format(f.assign_date,'%y%m%d') <= date_format(#{params.endAssignDate},'%y%m%d')


order by f.follow_up_id desc

select count(1) from gc_follow_up
where resident_id = #{residentId}
  and result_id = #{resultId}

mapper.update:
update gc_follow_up
follow_up_status = #{followUpStatus}, follow_up_level = #{followUpLevel}, assigned_user_id = #{assignedUserId}, assigned_user_name = #{assignedUserName}, assign_date = #{assignDate}, complete_date = #{completeDate}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where follow_up_id = #{followUpId}
